import{_ as p,a0 as t,w as o,s as l,ao as u,I as i,x as e,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180824 [Solved] -sub process usr bin dpkg returned an error code 1- Error in Ubuntu","title":"怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤","tag":"201809","desc":""},"relativePath":"201809/20180824 [Solved] -sub process usr bin dpkg returned an error code 1- Error in Ubuntu.md","filePath":"[post].md"}'),d={name:"201809/20180824 [Solved] -sub process usr bin dpkg returned an error code 1- Error in Ubuntu.md"};function b(g,s,c,h,k,f){const n=t("Link");return o(),l("div",null,[s[15]||(s[15]=u(`<h1 id="怎樣解決-ubuntu-中的-sub-process-usr-bin-dpkg-returned-an-error-code-1-錯誤" tabindex="-1">怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤 <a class="header-anchor" href="#怎樣解決-ubuntu-中的-sub-process-usr-bin-dpkg-returned-an-error-code-1-錯誤" aria-label="Permalink to “怎樣解決 Ubuntu 中的 “sub process usr bin dpkg returned an error code 1” 錯誤”">​</a></h1><blockquote><p>如果你在 Ubuntu Linux 上安裝軟件時遇到 “sub process usr bin dpkg returned an error code 1”，請按照以下步驟進行修復。</p></blockquote><p>Ubuntu 和其他基於 Debian 的發行版中的一個常見問題是已經損壞的包。你嘗試更新系統或安裝新軟件包時會遇到類似 “Sub-process /usr/bin/dpkg returned an error code” 的錯誤。</p><p>這就是前幾天發生在我身上的事。我試圖在 Ubuntu 中安裝一個電台程序時，它給我了這個錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Unpacking python-gst-1.0 (1.6.2-1build1) ...</span></span>
<span class="line"><span>Selecting previously unselected package radiotray.</span></span>
<span class="line"><span>Preparing to unpack .../radiotray_0.7.3-5ubuntu1_all.deb ...</span></span>
<span class="line"><span>Unpacking radiotray (0.7.3-5ubuntu1) ...</span></span>
<span class="line"><span>Processing triggers for man-db (2.7.5-1) ...</span></span>
<span class="line"><span>Processing triggers for desktop-file-utils (0.22-1ubuntu5.2) ...</span></span>
<span class="line"><span>Processing triggers for bamfdaemon (0.5.3~bzr0+16.04.20180209-0ubuntu1) ...</span></span>
<span class="line"><span>Rebuilding /usr/share/applications/bamf-2.index...</span></span>
<span class="line"><span>Processing triggers for gnome-menus (3.13.3-6ubuntu3.1) ...</span></span>
<span class="line"><span>Processing triggers for mime-support (3.59ubuntu1) ...</span></span>
<span class="line"><span>Setting up polar-bookshelf (1.0.0-beta56) ...</span></span>
<span class="line"><span>ln: failed to create symbolic link &#39;/usr/local/bin/polar-bookshelf&#39;: No such file or directory</span></span>
<span class="line"><span>dpkg: error processing package polar-bookshelf (--configure):</span></span>
<span class="line"><span>subprocess installed post-installation script returned error exit status 1</span></span>
<span class="line"><span>Setting up python-appindicator (12.10.1+16.04.20170215-0ubuntu1) ...</span></span>
<span class="line"><span>Setting up python-gst-1.0 (1.6.2-1build1) ...</span></span>
<span class="line"><span>Setting up radiotray (0.7.3-5ubuntu1) ...</span></span>
<span class="line"><span>Errors were encountered while processing:</span></span>
<span class="line"><span>polar-bookshelf</span></span>
<span class="line"><span>E: Sub-process /usr/bin/dpkg returned an error code (1)</span></span></code></pre></div><p>這裏最後三行非常重要。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Errors were encountered while processing:</span></span>
<span class="line"><span>polar-bookshelf</span></span>
<span class="line"><span>E: Sub-process /usr/bin/dpkg returned an error code (1)</span></span></code></pre></div><p>它告訴我 polar-bookshelf 包引發了問題。這可能對你如何修復這個錯誤至關重要。</p><h3 id="修復-sub-process-usr-bin-dpkg-returned-an-error-code-1" tabindex="-1">修復 Sub-process /usr/bin/dpkg returned an error code (1) <a class="header-anchor" href="#修復-sub-process-usr-bin-dpkg-returned-an-error-code-1" aria-label="Permalink to “修復 Sub-process /usr/bin/dpkg returned an error code (1)”">​</a></h3><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/fix-common-update-errors-ubuntu.jpeg" alt="Fix update errors in Ubuntu Linux"></p><p>讓我們嘗試修復這個損壞的錯誤包。我將展示幾種你可以逐一嘗試的方法。最初的那些易於使用，幾乎不用動腦子。</p><p>在試了這裏討論的每一種方法之後，你應該嘗試運行 <code>sudo apt update</code>，接着嘗試安裝新的包或升級。</p><h4 id="方法-1-重新配包資料庫" tabindex="-1">方法 1：重新配包資料庫 <a class="header-anchor" href="#方法-1-重新配包資料庫" aria-label="Permalink to “方法 1：重新配包資料庫”">​</a></h4><p>你可以嘗試的第一種方法是重新配置包資料庫。資料庫可能在安裝包時損壞了。重新配置通常可以解決問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg --configure -a</span></span></code></pre></div><h4 id="方法-2-強制安裝" tabindex="-1">方法 2：強制安裝 <a class="header-anchor" href="#方法-2-強制安裝" aria-label="Permalink to “方法 2：強制安裝”">​</a></h4><p>如果是之前包安裝過程被中斷，你可以嘗試強制安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install -f</span></span></code></pre></div><h4 id="方法3-嘗試刪除有問題的包" tabindex="-1">方法3：嘗試刪除有問題的包 <a class="header-anchor" href="#方法3-嘗試刪除有問題的包" aria-label="Permalink to “方法3：嘗試刪除有問題的包”">​</a></h4><p>如果這不是你的問題，你可以嘗試手動刪除包。但不要對 Linux 內核包（以 linux- 開頭）執行此操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove</span></span></code></pre></div><h4 id="方法-4-刪除有問題的包中的信息文件" tabindex="-1">方法 4：刪除有問題的包中的信息文件 <a class="header-anchor" href="#方法-4-刪除有問題的包中的信息文件" aria-label="Permalink to “方法 4：刪除有問題的包中的信息文件”">​</a></h4><p>這應該是你最後的選擇。你可以嘗試從 <code>/var/lib/dpkg/info</code> 中刪除與相關軟件包關聯的文件。</p><p><strong>你需要了解一些基本的 Linux 命令來了解發生了什麼以及如何對應你的問題</strong></p><p>就我而言，我在 polar-bookshelf 中遇到問題。所以我查找了與之關聯的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l /var/lib/dpkg/info | grep -i polar-bookshelf</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 2324811 Aug 14 19:29 polar-bookshelf.list</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 2822824 Aug 10 04:28 polar-bookshelf.md5sums</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root 113 Aug 10 04:28 polar-bookshelf.postinst</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root 84 Aug 10 04:28 polar-bookshelf.postrm</span></span></code></pre></div><p>現在我需要做的就是刪除這些文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /var/lib/dpkg/info/polar-bookshelf.* /tmp</span></span></code></pre></div><p>使用 <code>sudo apt update</code>，接着你應該就能像往常一樣安裝軟件了。</p><h4 id="哪種方法適合你-如果有效" tabindex="-1">哪種方法適合你（如果有效）？ <a class="header-anchor" href="#哪種方法適合你-如果有效" aria-label="Permalink to “哪種方法適合你（如果有效）？”">​</a></h4><p>我希望這篇快速文章可以幫助你修復 “E: Sub-process /usr/bin/dpkg returned an error code (1)” 的錯誤。</p><p>如果它對你有用，是那種方法？你是否設法使用其他方法修復此錯誤？如果是，請分享一下以幫助其他人解決此問題。</p><hr>`,33)),i("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://itsfoss.com/dpkg-returned-an-error-code-1/"},{default:r(()=>[...s[0]||(s[0]=[e("https://itsfoss.com/dpkg-returned-an-error-code-1/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://itsfoss.com/author/abhishek/"},{default:r(()=>[...s[2]||(s[2]=[e("Abhishek Prakash",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:r(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:r(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:r(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=p(d,[["render",b]]);export{y as __pageData,C as default};
